*{box-sizing:border-box} :root{--ink:#17212a;--paper:#f4f2e9;--orange:#ee6848;--gold:#e8bc69;--mono:'DM Mono',monospace;--display:'Outfit',sans-serif}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#101c2a;color:var(--paper);font-family:var(--display);touch-action:none}button,a{-webkit-tap-highlight-color:transparent}.game-shell{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#a7c7d4;isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(13,25,37,.36),transparent 25%,transparent 66%,rgba(12,21,30,.28)),linear-gradient(90deg,rgba(12,21,30,.15),transparent 25%,transparent 75%,rgba(12,21,30,.11));z-index:1}.topbar{position:absolute;z-index:5;left:5.1%;right:5.1%;top:clamp(20px,4.2vh,42px);display:flex;align-items:center;justify-content:space-between}.brand{font-weight:900;font-size:20px;letter-spacing:.105em;text-decoration:none;color:#fff;text-shadow:0 2px 20px #314754}.brand-mark{font-size:15px;margin-right:8px;color:#f5c576}.brand-dot{color:#f19167}.top-right{display:flex;align-items:center;gap:22px}.weather,.eyebrow,.footer,.keyboard-hint,.best-run,.edition,.stamina-hint{font-family:var(--mono);letter-spacing:.12em;font-size:9px}.weather{display:flex;align-items:center;gap:9px;text-shadow:0 1px 5px #47606b}.weather i{width:6px;height:6px;border-radius:50%;background:#c9e6c6;box-shadow:0 0 10px #d9ffbd}.sound-btn{width:36px;height:36px;border:1px solid #ffffff62;background:#ffffff20;color:white;border-radius:50%;font-size:17px;cursor:pointer;backdrop-filter:blur(8px)}.hud{position:absolute;z-index:4;top:15.5%;left:5.2%;right:5.2%;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none;text-shadow:0 2px 14px #32505c}.altitude{width:145px;position:relative}.eyebrow{display:block;color:#f9f7e9b5;font-size:8px}.altitude strong{font-size:37px;line-height:1.07;font-weight:600;letter-spacing:-.05em}.unit{font-family:var(--mono);font-size:11px;margin-left:6px;color:#f3d79a}.alt-track{height:2px;background:#ffffff52;width:100%;margin-top:11px}.alt-track i{display:block;background:#f2c877;height:100%;width:0;box-shadow:0 0 8px #f4c578}.hud-center{text-align:center;padding-top:1px}.hud-center strong{font-weight:500;display:block;font-size:16px;letter-spacing:.02em;margin-top:6px}.hud-center small{font-size:9px;font-family:var(--mono);color:#e6d09d}.stats{display:flex;align-items:center;gap:5px}.stats .stat-icon{font-size:18px;color:#ffe08c;text-shadow:0 0 12px #ffcf65}.stats strong{font-size:18px;font-weight:600}.stats .eyebrow{margin-left:3px}.stamina-wrap{position:absolute;z-index:4;left:50%;top:28%;transform:translateX(-50%);width:min(230px,42vw);text-align:center;transition:opacity .3s;opacity:.9}.stamina-bar{width:100%;height:4px;background:#ffffff5a;margin-top:6px;border-radius:5px;overflow:hidden}.stamina-bar i{display:block;width:100%;height:100%;background:#f2d189;transition:width .14s linear}.stamina-hint{display:block;font-size:7px;margin-top:7px;color:#fff9;letter-spacing:.18em}.controls{position:absolute;z-index:6;left:max(5%,env(safe-area-inset-left));right:max(5%,env(safe-area-inset-right));bottom:max(9%,env(safe-area-inset-bottom));display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.move-controls{display:flex;gap:11px;pointer-events:auto}.control-btn,.climb-btn{pointer-events:auto;color:#fff;background:#f6f1e52b;border:1px solid #ffffff73;backdrop-filter:blur(9px);cursor:pointer;touch-action:none;user-select:none;box-shadow:0 5px 25px #152d3c25}.control-btn{height:58px;width:58px;border-radius:50%;font-size:35px;font-family:var(--display);font-weight:300;line-height:1;padding-bottom:5px}.control-btn:active,.climb-btn:active,.control-btn.pressed,.climb-btn.pressed{background:#ee7956cc;transform:scale(.96)}.climb-btn{height:70px;width:85px;border-radius:50%;background:#e87652e8;border:1px solid #ffb59c;color:white;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;box-shadow:0 8px 26px #703a2e55}.climb-btn span{font-size:23px;line-height:21px}.climb-btn b{font:500 8px var(--mono);letter-spacing:.15em}.keyboard-hint{position:absolute;z-index:4;bottom:4.4%;left:50%;transform:translateX(-50%);font-size:8px;color:#ffffffe0;text-shadow:0 1px 5px #213c4b;white-space:nowrap;letter-spacing:.12em}.keyboard-hint span{padding:0 9px;color:#f6cb83}.footer{position:absolute;z-index:5;bottom:3.2%;left:5.1%;right:5.1%;display:flex;justify-content:space-between;color:#ffffffa8;font-size:7px}.footer i{font-style:normal;padding:0 4px;color:#f3c780}.screen{position:absolute;inset:0;z-index:8;display:flex;align-items:center;justify-content:flex-start;padding:clamp(96px,15vh,150px) 7.3% 60px;background:linear-gradient(90deg,rgba(18,34,44,.64),rgba(22,41,49,.3) 44%,transparent 77%)}.intro-card{width:min(470px,57vw);margin-top:0;text-shadow:0 2px 22px #1a2e38}.edition{color:#f4d18e;display:flex;align-items:center;gap:10px;font-size:8px}.edition span{width:22px;height:1px;background:#f4d18e}.intro-card h1{font-size:clamp(54px,8vw,106px);line-height:.83;letter-spacing:-.075em;margin:28px 0 23px;font-weight:800}.intro-card h1 em{font-style:normal;color:#f2c777}.intro-copy{max-width:340px;font-weight:400;font-size:14px;line-height:1.6;color:#f5f4eddd;margin:0 0 24px}.briefing{display:flex;gap:22px;margin:0 0 27px}.briefing>div{display:flex;gap:8px;align-items:center;font:500 8px var(--mono);letter-spacing:.06em;line-height:1.7;color:#fff}.briefing small{font-size:7px;color:#ffffffa8;letter-spacing:0;font-family:var(--display)}.brief-icon{font-family:var(--display);font-size:19px;color:#f5cc7e}.primary-btn{height:49px;min-width:190px;padding:0 18px;border:0;border-radius:2px;background:#f2ca7d;color:#292d2d;font:600 10px var(--mono);letter-spacing:.1em;cursor:pointer;box-shadow:0 10px 24px #172f3833;transition:transform .18s,background .18s}.primary-btn:hover{transform:translateY(-2px);background:#ffdb91}.primary-btn span{font-size:16px;margin-left:25px}.best-run{margin-top:18px;font-size:7px;color:#ffffff9a;letter-spacing:.13em}.best-run b{color:#f7d087;font-weight:400;margin-left:8px}.scroll-note{position:absolute;right:5.3%;bottom:14%;font:8px var(--mono);letter-spacing:.16em;color:#ffffffb8;writing-mode:vertical-rl;display:flex;gap:12px;align-items:center}.scroll-note span{font-size:15px;color:#f3ca7c}.hidden{display:none!important}.result-screen{justify-content:center;align-items:center;padding:20px;background:#10202bb0;backdrop-filter:blur(7px)}.result-card{text-align:center;width:min(420px,90vw);padding:48px 40px;background:#152733e8;border:1px solid #ffffff37;box-shadow:0 25px 80px #10202b80}.result-kicker{font:9px var(--mono);letter-spacing:.2em;color:#f3ca7c}.result-card h2{font-size:clamp(38px,7vw,65px);letter-spacing:-.06em;margin:15px 0 6px}.result-card p{color:#ffffffab;font-size:14px}.result-stats{display:flex;justify-content:center;gap:50px;margin:30px 0}.result-stats div{display:flex;flex-direction:column;gap:8px}.result-stats span{font:8px var(--mono);letter-spacing:.1em;color:#ffffff8c}.result-stats b{font-size:17px;font-weight:600}.toast{position:absolute;z-index:7;top:39%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#142833c9;border:1px solid #ffffff35;padding:10px 15px;color:#fff4db;font:9px var(--mono);letter-spacing:.1em;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:700px){.topbar{left:6%;right:6%;top:max(18px,env(safe-area-inset-top))}.brand{font-size:17px}.weather{font-size:7px}.top-right{gap:12px}.sound-btn{width:32px;height:32px}.hud{top:12%;left:6%;right:6%}.altitude{width:105px}.altitude strong{font-size:30px}.alt-track{margin-top:7px}.hud-center strong{font-size:13px}.stats{gap:4px}.stats .eyebrow{display:none}.stamina-wrap{top:22%;width:38vw}.controls{bottom:max(11%,calc(env(safe-area-inset-bottom) + 35px));left:6%;right:6%}.control-btn{width:54px;height:54px}.climb-btn{width:74px;height:66px}.keyboard-hint{display:none}.footer{bottom:max(3%,env(safe-area-inset-bottom));font-size:6px}.screen{padding:105px 7% 85px;align-items:flex-start;background:linear-gradient(90deg,rgba(18,34,44,.64),rgba(22,41,49,.34) 63%,rgba(22,41,49,.05))}.intro-card{width:min(460px,100%);margin-top:3vh}.intro-card h1{font-size:clamp(58px,15vw,91px);margin:22px 0 15px}.intro-copy{font-size:12px;max-width:305px;margin-bottom:18px}.briefing{gap:12px;margin-bottom:20px}.briefing>div{gap:5px;font-size:7px}.briefing small{font-size:6px}.brief-icon{font-size:16px}.edition{font-size:7px}.primary-btn{height:46px}.scroll-note{display:none}.best-run{margin-top:12px}.result-card{padding:40px 22px}.result-stats{gap:28px}.stamina-hint{font-size:6px}}
@media(max-height:640px) and (min-width:701px){.screen{padding-top:80px;padding-bottom:45px}.intro-card h1{font-size:58px;margin:15px 0}.intro-copy{font-size:12px;margin-bottom:14px}.briefing{margin-bottom:14px}.primary-btn{height:43px}.best-run{margin-top:9px}.hud{top:13%}.stamina-wrap{top:26%}.controls{bottom:8%}}

(() => {
  'use strict';
  const canvas = document.getElementById('scene');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { altitude: $('altitudeValue'), remaining: $('remainingValue'), gems: $('crystalValue'), fill: $('altFill'), stamina: $('staminaFill'), hint: $('staminaHint'), intro: $('introScreen'), result: $('resultScreen'), resultTitle: $('resultTitle'), resultKicker: $('resultKicker'), resultCopy: $('resultCopy'), resultAlt: $('resultAltitude'), resultGems: $('resultGems'), best: $('bestRun'), toast: $('toast') };
  const MAX_Y = 1000;
  let W = 0, H = 0, dpr = 1, last = 0, toastTimer = 0, state = 'intro', muted = false, audio = null;
  let run = freshRun();
  const input = { left: false, right: false, climb: false };
  const rand = (n) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
  function freshRun() { return { y: 0, lane: 0, stamina: 100, gems: 0, shake: 0, flash: 0, steps: 0, collected: new Set(), hit: new Set(), particles: [], startAt: 0, checkpoint: 0 }; }
  function resize() { const r = canvas.getBoundingClientRect(); W = r.width; H = r.height; dpr = Math.min(window.devicePixelRatio || 1, 2); canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr); ctx.setTransform(dpr, 0, 0, dpr, 0, 0); }
  window.addEventListener('resize', resize); resize();
  function ground(y) { return y * .50 + Math.sin(y * .047) * .22 + Math.sin(y * .013) * .45; }
  function route(y) { return Math.sin(y * .0105) * 4.2 + Math.sin(y * .027 + .8) * 1.4; }
  function camera() { return { y: run.y + 4.2, z: ground(run.y) + 1.7 }; }
  function project(x, y, z) {
    const c = camera();
    const dep = 13.2 + (c.y - y) * .84 + (z - c.z) * .54;
    if (dep < 1) return { x: -10000, y: -10000, s: 0, d: dep };
    const s = H * .83 / dep;
    const up = (y - c.y) * .54 + (z - c.z) * .84;
    return { x: W * .5 + x * s, y: H * .48 - up * s, s, d: dep };
  }
  function pathPoint(lane, y, z = ground(y) + .08) { return [route(y) + lane, y, z]; }
  const obstacles = [], crystals = [];
  for (let y = 24, i = 0; y < 1020; y += 20 + rand(i + 9) * 13, i++) {
    if (rand(i + 3) > .3) obstacles.push({ y, lane: (rand(i + 11) - .5) * 7.5, type: rand(i + 33) > .45 ? 'rock' : 'ice', id: 'o' + i, size: .8 + rand(i + 41) * .5 });
    if (i % 2 === 0 || rand(i + 88) > .57) crystals.push({ y: y + 8 + rand(i + 55) * 6, lane: (rand(i + 66) - .5) * 6.3, id: 'g' + i });
  }
  function drawPoly(points, fill, stroke = null, line = 1) { ctx.beginPath(); points.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)); ctx.closePath(); ctx.fillStyle = fill; ctx.fill(); if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = line; ctx.stroke(); } }
  function gradientSky() {
    const g = ctx.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#7da8bb'); g.addColorStop(.38, '#b8d2d3'); g.addColorStop(.69, '#e8d9bf'); g.addColorStop(1, '#a7b9b1');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    const glow = ctx.createRadialGradient(W * .73, H * .19, 0, W * .73, H * .19, H * .52);
    glow.addColorStop(0, '#fff3d4a3'); glow.addColorStop(.22, '#fff1d444'); glow.addColorStop(1, '#fff3d400'); ctx.fillStyle = glow; ctx.fillRect(0, 0, W, H);
    const sun = ctx.createRadialGradient(W * .73, H * .19, 2, W * .73, H * .19, 28); sun.addColorStop(0, '#fff8df'); sun.addColorStop(.32, '#ffedc5d9'); sun.addColorStop(1, '#ffedc500'); ctx.fillStyle = sun; ctx.beginPath(); ctx.arc(W * .73, H * .19, 28, 0, Math.PI * 2); ctx.fill();
    drawDistantMountains();
  }
  function drawDistantMountains() {
    const horizon = H * .51;
    for (let layer = 0; layer < 3; layer++) {
      const base = horizon + layer * H * .048;
      const pts = [{ x: 0, y: H }];
      for (let i = 0; i <= 12; i++) {
        const x = i * W / 12;
        let peak = base - H * (.18 + rand(i + layer * 17) * .21);
        if (i % 3 === layer) peak -= H * .12;
        pts.push({ x, y: peak });
        pts.push({ x: x + W / 24, y: peak + H * (.08 + rand(i + layer * 29) * .1) });
      }
      pts.push({ x: W, y: H });
      drawPoly(pts, ['#839e9e','#758c8e','#65797d'][layer]);
      // Snow facets on the ridges.
      ctx.globalAlpha = .65 - layer * .12;
      for (let i = 0; i < 12; i += 3) {
        const x = i * W / 12, peak = base - H * (.18 + rand(i + layer * 17) * .21) - (i % 3 === layer ? H * .12 : 0);
        drawPoly([{x,y:peak},{x:x+W/24,y:peak+H*.09},{x:x+W/24+W/36,y:peak+H*.03}], '#e5e8dc');
      }
      ctx.globalAlpha = 1;
    }
    const mist = ctx.createLinearGradient(0, horizon - 40, 0, horizon + H * .12); mist.addColorStop(0, '#e9e4d400'); mist.addColorStop(.68, '#e8e4d977'); mist.addColorStop(1, '#e8e4d900'); ctx.fillStyle = mist; ctx.fillRect(0, horizon - 40, W, H * .2);
  }
  function terrainHeight(offset, y) {
    const p = ground(y);
    const fall = Math.max(0, Math.abs(offset) - 4.5) * .39;
    return p - fall + Math.sin(y * .16 + offset * .43) * .13 + Math.cos(offset * .32 + y * .09) * .16;
  }
  function drawTerrain() {
    const strips = [-34,-25,-18,-12,-8,-4.5,0,4.5,8,12,18,25,34];
    const cells = [];
    const start = Math.floor((run.y - 36) / 5) * 5;
    for (let y = start; y < run.y + 60; y += 5) {
      for (let j = 0; j < strips.length - 1; j++) {
        const a = strips[j], b = strips[j + 1], cy = y + 2.5;
        const coords = [[a,y],[b,y],[b,y+5],[a,y+5]];
        const ps = coords.map(([off, yy]) => { const z = terrainHeight(off, yy); return project(route(yy) + off, yy, z); });
        const d = ps.reduce((v,p)=>v+p.d,0)/4;
        const off = (a+b)/2;
        let col;
        const n = Math.sin(y * .23 + j * 2.1) + Math.cos(y * .08 - j * 1.3);
        if (Math.abs(off) < 4.55) col = n > .55 ? '#a9a89a' : n < -.9 ? '#777f7b' : '#92948b';
        else if (Math.abs(off) < 9) col = n > .35 ? '#727c79' : '#626f70';
        else col = n > .5 ? '#687779' : '#536368';
        cells.push({ ps, d, col, off, y });
      }
    }
    cells.sort((a,b)=>b.d-a.d);
    cells.forEach(cell => {
      // Crackle each quad into subtle facets to keep the slope dimensional.
      const p=cell.ps, shade=(Math.sin(cell.y*.51+cell.off*2)*.5);
      drawPoly([p[0],p[1],p[2]], cell.col);
      drawPoly([p[0],p[2],p[3]], shade > .1 ? cell.col : '#536367');
      if (Math.abs(cell.off) < 4.55 && rand(Math.floor(cell.y*2)+Math.floor(cell.off*5)) > .84) {
        const q = p[0], r = p[2]; ctx.strokeStyle='#d5cec0';ctx.globalAlpha=.22;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo((q.x+r.x)/2+4,(q.y+r.y)/2+1);ctx.stroke();ctx.globalAlpha=1;
      }
    });
    // Snow shelves tucked into the upper rock faces.
    for (let y = start; y < run.y + 48; y += 14) {
      for (const side of [-1,1]) {
        if (rand(y + side * 4) < .42) continue;
        const off = side * (11 + rand(y + side * 21) * 13), yy = y + rand(y + 1) * 5;
        const pts = [[off,yy],[off+side*2,yy+1.8],[off-side*1.2,yy+2.6]].map(([o,v])=>project(route(v)+o,v,terrainHeight(o,v)+.06));
        drawPoly(pts, '#d6d9cd');
      }
    }
    drawTrailEdges(start);
  }
  function drawTrailEdges(start) {
    for (const side of [-1,1]) {
      const pts=[];
      for(let y=start;y<run.y+63;y+=3){const off=side*4.5;pts.push(project(route(y)+off,y,ground(y)+.095));}
      if(pts.length>1){ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);pts.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.strokeStyle='#c6bda8a0';ctx.lineWidth=Math.max(1,H/750);ctx.stroke();}
    }
  }
  function drawTree(x,y,scale) {
    const z=terrainHeight(x-route(y),y), base=project(x,y,z), s=base.s*scale;
    if(s<2||base.y>H+100||base.y<-200)return;
    const h=s*1.55, w=s*.6;
    ctx.fillStyle='#594d3f';ctx.fillRect(base.x-s*.055,base.y-h*.27,s*.11,h*.31);
    drawPoly([{x:base.x,y:base.y-h},{x:base.x-w*.67,y:base.y-h*.46},{x:base.x-w*.34,y:base.y-h*.48},{x:base.x-w,y:base.y-h*.11},{x:base.x+w,y:base.y-h*.11},{x:base.x+w*.36,y:base.y-h*.48},{x:base.x+w*.64,y:base.y-h*.47}], '#334e4c');
    drawPoly([{x:base.x,y:base.y-h},{x:base.x-w*.67,y:base.y-h*.46},{x:base.x,y:base.y-h*.53}], '#78918a');
    drawPoly([{x:base.x,y:base.y-h*.66},{x:base.x-w*.98,y:base.y-h*.11},{x:base.x,y:base.y-h*.2}], '#49655f');
  }
  function drawScenery() {
    const near=Math.floor((run.y-35)/6)*6;
    for(let y=near;y<run.y+56;y+=6){for(const side of [-1,1]){
      const key=Math.floor(y/6)+side*30;
      if(rand(key*2.7+side*9)>.45){const off=side*(8+rand(key+5)*22), xx=route(y)+off;drawTree(xx,y, .58+rand(key+7)*.65);}
      if(rand(key+52)>.55){const off=side*(7+rand(key+14)*23), z=terrainHeight(off,y); const p=project(route(y)+off,y,z);const s=p.s*(.24+rand(key+78)*.3); if(s>1&&p.y<H+40){ctx.fillStyle='#64716e';ctx.beginPath();ctx.ellipse(p.x,p.y-s*.15,s,s*.45,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#87928a';ctx.beginPath();ctx.ellipse(p.x-s*.18,p.y-s*.22,s*.54,s*.2,-.25,0,Math.PI*2);ctx.fill();}}
    }}
  }
  function drawRock(o) {
    const [x,y,z]=pathPoint(o.lane,o.y), p=project(x,y,z), s=p.s*o.size;
    if(p.d<0||p.y>H+120||p.y<-180)return;
    const shadow=project(x,y,z+.03);ctx.fillStyle='#26363b55';ctx.beginPath();ctx.ellipse(shadow.x,shadow.y,s*1.25,s*.37,0,0,Math.PI*2);ctx.fill();
    drawPoly([{x:p.x-s*.88,y:p.y},{x:p.x-s*.83,y:p.y-s*.48},{x:p.x-s*.34,y:p.y-s*.84},{x:p.x+s*.26,y:p.y-s*.76},{x:p.x+s*.83,y:p.y-s*.37},{x:p.x+s*.92,y:p.y-s*.06}], o.type==='ice'?'#9db9b5':'#596568', '#c4c6b8', Math.max(1,p.s*.025));
    drawPoly([{x:p.x-s*.34,y:p.y-s*.84},{x:p.x+s*.26,y:p.y-s*.76},{x:p.x+s*.83,y:p.y-s*.37},{x:p.x+s*.17,y:p.y-s*.45}], o.type==='ice'?'#d0e0d5':'#858e89');
    drawPoly([{x:p.x-s*.83,y:p.y-s*.48},{x:p.x-s*.34,y:p.y-s*.84},{x:p.x+s*.17,y:p.y-s*.45},{x:p.x-s*.28,y:p.y-s*.33}], o.type==='ice'?'#b9d1cc':'#707a77');
    if(o.type==='ice'){ctx.strokeStyle='#eff4e5';ctx.globalAlpha=.7;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-s*.18,p.y-s*.65);ctx.lineTo(p.x+s*.28,p.y-s*.15);ctx.stroke();ctx.globalAlpha=1;}
  }
  function drawGem(g) {
